package com.slowscape;

import net.runelite.client.config.ConfigManager;

final class SlowScapeConfigStateStore implements SlowScapeStateStore
{
	static final String GROUP = "slowscape";
	private static final String KEY_STATE_DATE = "stateDate";
	private static final String KEY_ACTION_COUNT = "actionCount";
	private static final String KEY_FIRST_ACTION = "firstAction";
	private static final String KEY_FIRST_ACTION_AT = "firstActionAt";
	private static final String KEY_LAST_ACTION = "lastAction";

	private final ConfigManager configManager;

	SlowScapeConfigStateStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	@Override
	public SlowScapeDailyRecord load()
	{
		return SlowScapeDailyRecord.of(
			configManager.getRSProfileConfiguration(GROUP, KEY_STATE_DATE),
			parseInt(configManager.getRSProfileConfiguration(GROUP, KEY_ACTION_COUNT)),
			configManager.getRSProfileConfiguration(GROUP, KEY_FIRST_ACTION),
			configManager.getRSProfileConfiguration(GROUP, KEY_FIRST_ACTION_AT),
			configManager.getRSProfileConfiguration(GROUP, KEY_LAST_ACTION));
	}

	@Override
	public void save(SlowScapeDailyRecord record)
	{
		if (record == null || record.getDate().isEmpty())
		{
			configManager.unsetRSProfileConfiguration(GROUP, KEY_STATE_DATE);
			configManager.unsetRSProfileConfiguration(GROUP, KEY_ACTION_COUNT);
			configManager.unsetRSProfileConfiguration(GROUP, KEY_FIRST_ACTION);
			configManager.unsetRSProfileConfiguration(GROUP, KEY_FIRST_ACTION_AT);
			configManager.unsetRSProfileConfiguration(GROUP, KEY_LAST_ACTION);
			return;
		}

		configManager.setRSProfileConfiguration(GROUP, KEY_STATE_DATE, record.getDate());
		configManager.setRSProfileConfiguration(GROUP, KEY_ACTION_COUNT, Integer.toString(record.getActionCount()));
		configManager.setRSProfileConfiguration(GROUP, KEY_FIRST_ACTION, record.getFirstAction());
		configManager.setRSProfileConfiguration(GROUP, KEY_FIRST_ACTION_AT, record.getFirstActionAt());
		configManager.setRSProfileConfiguration(GROUP, KEY_LAST_ACTION, record.getLastAction());
	}

	private static int parseInt(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return 0;
		}

		try
		{
			return Integer.parseInt(value.trim());
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}
}

package com.slowscape;

import java.time.Instant;
import java.time.LocalDate;

final class SlowScapeDailyRecord
{
	private static final SlowScapeDailyRecord EMPTY = new SlowScapeDailyRecord("", 0, "", "", "");

	private final String date;
	private final int actionCount;
	private final String firstAction;
	private final String firstActionAt;
	private final String lastAction;

	private SlowScapeDailyRecord(String date, int actionCount, String firstAction, String firstActionAt, String lastAction)
	{
		this.date = clean(date);
		this.actionCount = Math.max(0, actionCount);
		this.firstAction = clean(firstAction);
		this.firstActionAt = clean(firstActionAt);
		this.lastAction = clean(lastAction);
	}

	static SlowScapeDailyRecord empty()
	{
		return EMPTY;
	}

	static SlowScapeDailyRecord of(String date, int actionCount, String firstAction, String firstActionAt, String lastAction)
	{
		if (date == null || date.trim().isEmpty())
		{
			return empty();
		}

		return new SlowScapeDailyRecord(date, actionCount, firstAction, firstActionAt, lastAction);
	}

	SlowScapeDailyRecord forDate(LocalDate today)
	{
		return isForDate(today) ? this : emptyForDate(today);
	}

	SlowScapeDailyRecord recordAction(LocalDate today, Instant now, String actionSummary)
	{
		String summary = clean(actionSummary);
		if (summary.isEmpty())
		{
			summary = "Counted action";
		}

		String todayString = today.toString();
		String timestamp = now.toString();
		if (actionCount == 0 || !isForDate(today))
		{
			return new SlowScapeDailyRecord(todayString, 1, summary, timestamp, summary);
		}

		return new SlowScapeDailyRecord(date, actionCount + 1, firstAction, firstActionAt, summary);
	}

	boolean isForDate(LocalDate today)
	{
		return today != null && today.toString().equals(date);
	}

	boolean hasSpentAction()
	{
		return actionCount > 0;
	}

	String getDate()
	{
		return date;
	}

	int getActionCount()
	{
		return actionCount;
	}

	String getFirstAction()
	{
		return firstAction;
	}

	String getFirstActionAt()
	{
		return firstActionAt;
	}

	String getLastAction()
	{
		return lastAction;
	}

	private static SlowScapeDailyRecord emptyForDate(LocalDate today)
	{
		return new SlowScapeDailyRecord(today == null ? "" : today.toString(), 0, "", "", "");
	}

	private static String clean(String value)
	{
		return value == null ? "" : value.trim();
	}
}

package com.slowscape;

import java.time.Instant;
import java.time.LocalDate;
import java.util.function.Supplier;

final class SlowScapeDailyTracker
{
	private final SlowScapeStateStore stateStore;
	private final Supplier<LocalDate> todaySupplier;
	private final Supplier<Instant> nowSupplier;

	SlowScapeDailyTracker(SlowScapeStateStore stateStore, Supplier<LocalDate> todaySupplier, Supplier<Instant> nowSupplier)
	{
		this.stateStore = stateStore;
		this.todaySupplier = todaySupplier;
		this.nowSupplier = nowSupplier;
	}

	SlowScapeActionGateResult trySpend(String actionSummary, boolean allowExtraActionsToday)
	{
		LocalDate today = todaySupplier.get();
		SlowScapeDailyRecord record = loadToday(today);
		if (!record.hasSpentAction())
		{
			SlowScapeDailyRecord updated = record.recordAction(today, nowSupplier.get(), actionSummary);
			stateStore.save(updated);
			return SlowScapeActionGateResult.allowed(updated, false);
		}

		if (allowExtraActionsToday)
		{
			SlowScapeDailyRecord updated = record.recordAction(today, nowSupplier.get(), actionSummary);
			stateStore.save(updated);
			return SlowScapeActionGateResult.allowed(updated, true);
		}

		return SlowScapeActionGateResult.blocked(record);
	}

	boolean recordIfUnspent(String actionSummary)
	{
		LocalDate today = todaySupplier.get();
		SlowScapeDailyRecord record = loadToday(today);
		if (record.hasSpentAction())
		{
			return false;
		}

		stateStore.save(record.recordAction(today, nowSupplier.get(), actionSummary));
		return true;
	}

	boolean hasSpentToday()
	{
		return loadToday(todaySupplier.get()).hasSpentAction();
	}

	SlowScapeDailyRecord snapshot()
	{
		return loadToday(todaySupplier.get());
	}

	void resetToday()
	{
		stateStore.save(SlowScapeDailyRecord.empty().forDate(todaySupplier.get()));
	}

	private SlowScapeDailyRecord loadToday(LocalDate today)
	{
		SlowScapeDailyRecord record = stateStore.load();
		SlowScapeDailyRecord todayRecord = record.forDate(today);
		if (!todayRecord.isForDate(today) || !todayRecord.getDate().equals(record.getDate()))
		{
			stateStore.save(todayRecord);
		}
		return todayRecord;
	}
}

