package com.slowscape;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Instant;
import java.time.ZoneId;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class SlowScapeOverlay extends OverlayPanel
{
	private static final Color AVAILABLE = new Color(120, 220, 120);
	private static final Color SPENT = new Color(255, 150, 120);
	private static final Color OVERRIDE = new Color(255, 220, 120);
	private static final int OVERLAY_WIDTH = 230;
	private static final int LINE_TEXT_GAP = 8;

	private final SlowScapePlugin plugin;
	private final SlowScapeConfig config;
	private final SlowScapeOverlayModel model = new SlowScapeOverlayModel(ZoneId.systemDefault());

	@Inject
	SlowScapeOverlay(SlowScapePlugin plugin, SlowScapeConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPreferredSize(new Dimension(OVERLAY_WIDTH, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		SlowScapeDailyRecord record = plugin.getCurrentRecord();
		boolean override = config.allowExtraActionsToday();
		boolean spent = record.hasSpentAction();
		Color stateColor = override ? OVERRIDE : spent ? SPENT : AVAILABLE;
		List<SlowScapeOverlayLine> lines = model.lines(
			record,
			override,
			config.showUnlockTimer(),
			Instant.now(),
			plugin.getNextUnlock());

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("SlowScape")
			.color(stateColor)
			.build());

		FontMetrics metrics = graphics.getFontMetrics();
		for (SlowScapeOverlayLine line : lines)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(line.getLeft())
				.right(fitRightText(line, metrics))
				.rightColor(rightColor(line, stateColor))
				.build());
		}

		return super.render(graphics);
	}

	private static String fitRightText(SlowScapeOverlayLine line, FontMetrics metrics)
	{
		if (!"First".equals(line.getLeft()))
		{
			return line.getRight();
		}

		int contentWidth = OVERLAY_WIDTH - (ComponentConstants.STANDARD_BORDER * 2);
		int rightWidth = contentWidth - metrics.stringWidth(line.getLeft()) - LINE_TEXT_GAP;
		return SlowScapeTextFitter.fit(line.getRight(), metrics, rightWidth);
	}

	private static Color rightColor(SlowScapeOverlayLine line, Color stateColor)
	{
		if ("Status".equals(line.getLeft()))
		{
			return stateColor;
		}
		if ("Extra used".equals(line.getLeft()))
		{
			return OVERRIDE;
		}
		return Color.WHITE;
	}
}

package com.slowscape;

import java.util.Objects;

final class SlowScapeOverlayLine
{
	private final String left;
	private final String right;

	SlowScapeOverlayLine(String left, String right)
	{
		this.left = left;
		this.right = right;
	}

	String getLeft()
	{
		return left;
	}

	String getRight()
	{
		return right;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}

		if (!(other instanceof SlowScapeOverlayLine))
		{
			return false;
		}

		SlowScapeOverlayLine that = (SlowScapeOverlayLine) other;
		return Objects.equals(left, that.left) && Objects.equals(right, that.right);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(left, right);
	}
}

package com.slowscape;

import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

final class SlowScapeOverlayModel
{
	private static final DateTimeFormatter UNLOCK_FORMATTER = DateTimeFormatter
		.ofPattern("MMM d h:mm a", Locale.US);

	private final ZoneId zoneId;

	SlowScapeOverlayModel(ZoneId zoneId)
	{
		this.zoneId = zoneId;
	}

	List<SlowScapeOverlayLine> lines(
		SlowScapeDailyRecord record,
		boolean override,
		boolean showUnlockTimer,
		Instant now,
		Instant nextUnlock)
	{
		List<SlowScapeOverlayLine> lines = new ArrayList<>();
		boolean spent = record.hasSpentAction();

		lines.add(new SlowScapeOverlayLine("Date", record.getDate()));
		lines.add(new SlowScapeOverlayLine("Status", override ? "Override" : spent ? "Spent" : "Available"));
		lines.add(new SlowScapeOverlayLine("Actions", Integer.toString(record.getActionCount())));

		if (showUnlockTimer)
		{
			lines.add(new SlowScapeOverlayLine("Unlocks", UNLOCK_FORMATTER.format(nextUnlock.atZone(zoneId))));
			lines.add(new SlowScapeOverlayLine("Time left", formatRemaining(now, nextUnlock)));
		}

		if (override && record.getActionCount() > 1)
		{
			lines.add(new SlowScapeOverlayLine("Extra used", Integer.toString(record.getActionCount() - 1)));
		}

		if (spent)
		{
			lines.add(new SlowScapeOverlayLine("First", record.getFirstAction()));
		}

		return lines;
	}

	private static String formatRemaining(Instant now, Instant nextUnlock)
	{
		Duration duration = Duration.between(now, nextUnlock);
		if (duration.isNegative() || duration.isZero())
		{
			return "0m";
		}

		long totalMinutes = duration.toMinutes();
		long days = totalMinutes / (24 * 60);
		long hours = (totalMinutes % (24 * 60)) / 60;
		long minutes = totalMinutes % 60;
		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		return minutes + "m";
	}
}

package com.slowscape;

import com.google.inject.Provides;
import java.time.Duration;
